package i18n

// getRussianAspectInterpretation returns detailed interpretation for aspect events in Russian.
// Key format: planet1_aspect_planet2 (e.g. jupiter_sextile_moon)
// Supports bidirectional lookup: if planet1_aspect_planet2 not found, tries planet2_aspect_planet1
func getRussianAspectInterpretation(key string, isPositive bool) string {
	if text, ok := russianAspectInterpretations[key]; ok {
		return text
	}
	// Try reverse key: planet2_aspect_planet1
	if reverseKey := reverseAspectKey(key); reverseKey != "" {
		if text, ok := russianAspectInterpretations[reverseKey]; ok {
			return text
		}
	}
	
	// Check for minor aspects (semi-sextile, semi-square, sesquiquadrate, quincunx)
	parts := splitAspectKey(key)
	if len(parts) == 3 {
		aspect := parts[1]
		switch aspect {
		case "semi-sextile":
			return getRussianMinorAspectInterpretation(parts[0], parts[2], "semi-sextile", isPositive)
		case "semi-square":
			return getRussianMinorAspectInterpretation(parts[0], parts[2], "semi-square", isPositive)
		case "sesquiquadrate":
			return getRussianMinorAspectInterpretation(parts[0], parts[2], "sesquiquadrate", isPositive)
		case "quincunx":
			return getRussianMinorAspectInterpretation(parts[0], parts[2], "quincunx", isPositive)
		}
	}
	
	if isPositive {
		return "В это время энергии планет гармонизируются, принося позитивные возможности для развития. Подходящее время для использования этой благоприятной энергии и действий в связанных областях."
	}
	return "В это время планеты образуют сложный угол, который может принести напряжение или ситуации, требующие корректировки. Это возможность для обучения и роста."
}

// getRussianMinorAspectInterpretation returns interpretation for minor aspects in Russian
func getRussianMinorAspectInterpretation(planet1, planet2, aspect string, isPositive bool) string {
	switch aspect {
	case "semi-sextile":
		if isPositive {
			return "Эти планеты образуют **полусекстиль** (30°), принося **тонкую гармонию** и **небольшие возможности**. Хотя энергия менее интенсивна, чем у мажорных аспектов, хорошо для **небольших корректировок**, **оптимизации деталей**, **постепенного улучшения**. Время **тихого влияния**; хорошо для **терпеливого накопления**, **маленьких шагов вперёд**."
		}
		return "Эти планеты образуют **полусекстиль** (30°), принося **небольшое трение** или **детали, требующие корректировки**. Хотя влияние небольшое, хорошо для **внимания к деталям**, **небольших исправлений**, **избегания накопления мелких проблем**."
	case "semi-square":
		if isPositive {
			return "Эти планеты образуют **полуквадрат** (45°), принося **лёгкое напряжение** и **небольшие вызовы**. Хотя менее интенсивно, чем квадрат, хорошо для **небольших корректировок**, **тонкой настройки направления**, **роста под давлением**. Время **небольших испытаний**; хорошо для **терпения**, **постепенного улучшения**."
		}
		return "Эти планеты образуют **полуквадрат** (45°), принося **небольшой конфликт** или **детальные проблемы, требующие решения**. Хотя влияние небольшое, хорошо для **своевременной обработки**, **избегания накопления**, **решения до того, как мелкие проблемы вырастут**."
	case "sesquiquadrate":
		if isPositive {
			return "Эти планеты образуют **сесквиквадрат** (135°), принося **умеренное напряжение** и **энергию, требующую корректировки**. Хотя менее интенсивно, чем квадрат, хорошо для **активной корректировки**, **поиска баланса**, **роста через вызов**. Время **умеренных испытаний**; хорошо для **гибкости**, **гибкого ответа**."
		}
		return "Эти планеты образуют **сесквиквадрат** (135°), принося **умеренный конфликт** или **противоречия, требующие решения**. Хотя влияние умеренное, хорошо для **встречи с проблемами**, **поиска решений**, **учёбы через конфликт**."
	case "quincunx":
		if isPositive {
			return "Эти планеты образуют **квинконс** (150°), принося **несогласованность, требующую корректировки**. Хотя энергия несогласована, хорошо для **поиска баланса**, **корректировки направления**, **роста через дискомфорт**. Время **нуждающееся в адаптации**; хорошо для **открытости**, **гибкой корректировки**."
		}
		return "Эти планеты образуют **квинконс** (150°), принося **несогласованность** или **противоречия, требующие решения**. Хотя влияние тонкое, хорошо для **встречи с несогласованностью**, **поиска точки баланса**, **роста через корректировку**."
	}
	return ""
}

